const raw = $('Webhook Twilio').first().json;
const body = raw.body || raw.params?.body || {};
const ds = ['sent','delivered','read','failed','undelivered','queued','sending'];
if (ds.includes(body?.SmsStatus) || ds.includes(body?.MessageStatus)) return [];
const mensajeTexto = (body?.Body || '').trim();
const mediaUrl = body?.MediaUrl0 || '';
const esAudio = !mensajeTexto && !!mediaUrl;
if (!mensajeTexto && !esAudio) return [];
const from = body?.From || '';
const telefono = from.startsWith('whatsapp:') ? from.replace('whatsapp:+','') : (body?.WaId || '');
if (!telefono) return [];
return [{ json: { telefono, mensajeTexto, mediaUrl, tipoMensaje: esAudio ? 'audio' : 'texto' } }];

const config = $('Leer Configuracion').first().json;
const twilioAuth = 'Basic ' + Buffer.from(config.twilio_account_sid + ':' + config.twilio_auth_token).toString('base64');
const mediaUrl = $('Parsear Mensaje').first().json.mediaUrl;
return [{ json: { twilioAuth, mediaUrl } }];

const transcripcion = $input.first().json.text || '';
const telefono = $('Parsear Mensaje').first().json.telefono;
return [{ json: { telefono, mensajeTexto: transcripcion } }];

const parsed = $('Parsear Mensaje').first().json;
const telefono = parsed.telefono;
const mensajeTexto = parsed.tipoMensaje === 'audio'
  ? $('Inyectar Texto').first().json.mensajeTexto
  : parsed.mensajeTexto;
const normTel = t => { let s = String(t).replace(/\D/g, ''); if (s.startsWith('54')) s = s.slice(2); if (s.startsWith('9') && s.length >= 10) s = s.slice(1); return s; };
const telNorm = normTel(telefono);
const todos = $('Buscar Paciente').all();
const paciente = todos.find(i => normTel(i.json.telefono) === telNorm)?.json || {};
const esViejo = !paciente.ultimoMensaje || (Date.now() - new Date(paciente.ultimoMensaje).getTime()) > 30000;
const pendientes = esViejo ? '' : (paciente.mensajesPendientes || '');
const nuevosPendientes = pendientes ? pendientes + '\n' + mensajeTexto : mensajeTexto;
const timestamp = new Date().toISOString();
return [{ json: { telefono, nuevosPendientes, timestamp } }];

const acum = $('Preparar Acumulacion').first().json;
const todos = $('Re-leer Paciente').all();
const paciente = todos.find(i => String(i.json.telefono) === String(acum.telefono))?.json || {};
if ((paciente.ultimoMensaje || '') !== acum.timestamp) return [];
return [{ json: { telefono: acum.telefono, mensajesCombinados: paciente.mensajesPendientes || '' } }];

const config = $('Construir Prompt').first().json;
const debounce = $('Verificar Debounce').first().json;
const rawResp = $input.first().json;
const historialItems = Array.isArray(rawResp) ? rawResp : $input.all().map(i => i.json).filter(i => i.role);
let historialTexto = '';
if (historialItems.length > 0) {
  const lineas = historialItems.map(h => (h.role === 'user' ? 'Usuario' : 'Recepcionista') + ': ' + h.content).join('\n');
  historialTexto = '[HISTORIAL]:\n' + lineas + '\n\n';
}
const textoAgente = historialTexto + '[TELEFONO]: ' + debounce.telefono + '\n[MENSAJE]: ' + debounce.mensajesCombinados;
return [{ json: { textoAgente, telefono: debounce.telefono, mensajesCombinados: debounce.mensajesCombinados, systemPrompt: config.systemPrompt, twilioFrom: config.twilioFrom, twilioUrl: config.twilioUrl, twilioAuth: config.twilioAuth, supabaseUrl: config.supabaseUrl, supabaseKey: config.supabaseKey, clinicaId: config.clinicaId } }];

const debounce = $('Verificar Debounce').first().json;
const config = $('Construir Prompt').first().json;
const agentOutput = $('Agente Recepcionista').first().json;
return [{ json: { supabaseUrl: config.supabaseUrl, supabaseKey: config.supabaseKey, telefono: debounce.telefono, clinica_id: config.clinicaId, userContent: debounce.mensajesCombinados || '', assistantContent: agentOutput.output || '' } }];

const config = $('Leer Configuracion').first().json;
const debounce = $('Verificar Debounce').first().json;
const agentData = $('Agente Recepcionista').first().json;
const errorMsg = agentData.error?.message || agentData.error || 'Error desconocido en el agente IA';
const adminTel = String(config.telefono_admin || '').replace(/\D/g, '');
const mensajeAdmin = '\u26a0\ufe0f Error en RecepIA\n\nPaciente: +' + debounce.telefono + '\nMensaje: ' + String(debounce.mensajesCombinados || '(sin mensaje)').slice(0, 300) + '\nError t\u00e9cnico: ' + String(errorMsg).slice(0, 300);
const twilioAuth = $('Construir Prompt').first().json.twilioAuth;
const twilioUrl = $('Construir Prompt').first().json.twilioUrl;
const twilioFrom = $('Construir Prompt').first().json.twilioFrom;
return [{ json: { adminTel, mensajeAdmin, twilioAuth, twilioUrl, twilioFrom } }];
